def patch(source):
    if 'const GenerationCoverage=(()=>{' in source:return source
    def replace(old,new,count=1):
        nonlocal source
        assert source.count(old)==count, f'coverage anchor {source.count(old)} != {count}: {old[:100]}'
        source=source.replace(old,new)
    helper=r"""const GenerationCoverage=(()=>{
 const weights=Object.freeze(__JSON__),weight=k=>weights[k]||1;
 const armyWeight=roster=>{const kinds=[...new Set(roster)];return kinds.reduce((s,k)=>s+weight(k),0)/Math.max(1,kinds.length);};
 function pick(kinds,r){if(!kinds.length)throw Error('EMPTY_COVERAGE_POOL');let n=r()*kinds.reduce((s,k)=>s+weight(k),0);for(const k of kinds){n-=weight(k);if(n<0)return k;}return kinds[kinds.length-1];}
 function shuffle(kinds,r){return kinds.map((k,i)=>({k,i,n:-Math.log(Math.max(Number.MIN_VALUE,r()))/weight(k)})).sort((a,b)=>a.n-b.n||a.i-b.i).map(x=>x.k);}
 return {weight,armyWeight,pick,shuffle};
})();
""".replace('__JSON__',json.dumps(WEIGHTS,sort_keys=True,separators=(',',':')))
    replace('const MatchupHistory=(()=>{',helper+'const MatchupHistory=(()=>{')
    replace('weights=candidates.map(c=>1/(1+4*run.stats(c.roster).meanUses)**2)', 'weights=candidates.map(c=>GenerationCoverage.armyWeight(c.roster)/(1+4*run.stats(c.roster).meanUses)**2)')
    replace('const a=rightPool.slice();for(let j=a.length-1;j>0;j--){const n=Math.floor(r()*(j+1));[a[j],a[n]]=[a[n],a[j]]}', 'const a=GenerationCoverage.shuffle(rightPool,r);')
    replace('const shuffled=(input,r)=>{const out=input.slice();for(let i=out.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[out[i],out[j]]=[out[j],out[i]]}return out};', 'const shuffled=(input,r)=>GenerationCoverage.shuffle(input,r);')
    replace('kinds.push(allowed[Math.floor(r()*allowed.length)]);', 'kinds.push(GenerationCoverage.pick(allowed,r));')
    replace('kinds.push(supportPool[Math.floor(r()*supportPool.length)])', 'kinds.push(GenerationCoverage.pick(supportPool,r))')
    replace('const first=elites[Math.floor(r()*elites.length)]', 'const first=GenerationCoverage.pick(elites,r)')
    return source
